import jakarta.persistence.*;

@Entity
@Table(name = "customers")
public class Customer {
    @Id  // Marks this as the primary key
    @GeneratedValue(strategy = GenerationType.IDENTITY)  // Auto-increment
    private Long id;

    @Column(nullable = false, unique = true)
    private String email;

    @Column(nullable = false)
    private String name;

    // Composite key example in a junction table
}

@Entity
@Table(name = "order_items")
public class OrderItem {
    @EmbeddedId  // Uses both columns together as primary key
    private OrderItemId id;

    private Integer quantity;
    private Double price;
}

import jakarta.persistence.*;

@Entity
@Table(name = "orders")
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)  // Foreign key relationship
    @JoinColumn(name = "customer_id", nullable = false)
    private Customer customer;  // Hibernate maps this to customer_id column

    private Double totalAmount;
    private String status;
}

