import jakarta.persistence.*;
import java.io.Serializable;

@Embeddable
record OrderItemId(Long orderId, Long productId) implements Serializable {}

@Entity
@Table(name = "order_items")
public class OrderItem {
    @EmbeddedId  // Composite primary key
    private OrderItemId id;

    @ManyToOne
    @MapsId("orderId")  // Maps orderId part of composite key to this relationship
    @JoinColumn(name = "order_id")
    private Order order;

    @ManyToOne
    @MapsId("productId")  // Maps productId part to this relationship
    @JoinColumn(name = "product_id")
    private Product product;

    private Integer quantity;  // Additional data about this relationship
    private Double priceAtPurchase;
}

